// src/pages/Profile.js

import { FiSettings } from "react-icons/fi";
import { useNavigate } from "react-router-dom";

const books = [
  {
    title: "노르웨이의 숲",
    review:
      "상실과 외로움 속에서도 사람 사이의 연결이 얼마나 중요한지를 보여주는 작품이었다.",
  },

  {
    title: "데미안",
    review:
      "진짜 나 자신을 찾아가는 과정이 인상 깊었다. 성장에 대한 고민이 많이 남는 책이었다.",
  },

  {
    title: "어린왕자",
    review:
      "어른이 된다는 것에 대해 다시 생각하게 만드는 따뜻한 이야기였다.",
  },

  {
    title: "1984",
    review:
      "통제된 사회가 얼마나 무서운지를 강렬하게 보여주는 작품이었다.",
  },

  {
    title: "해변의 카프카",
    review:
      "몽환적이고 신비로운 분위기가 오래 기억에 남았다.",
  },

  {
    title: "채식주의자",
    review:
      "인간의 내면과 억압에 대해 깊게 생각하게 되는 작품이었다.",
  },
];

function Profile() {
  const navigate = useNavigate();

  return (
    <div className="page">
      {/* 상단 */}
      <div className="profile-header">
        <div className="logo">
          READLY
        </div>

        <FiSettings className="setting-icon" />
      </div>

      {/* 프로필 */}
      <div className="profile-top">
        <div className="profile-image"></div>

        <div className="profile-info">
          <div className="profile-name">
            김연재 ✏️
          </div>

          <div className="follow-wrap">
            <div className="follow-box">
              <div className="follow-num">
                100
              </div>

              <div className="follow-text">
                팔로워
              </div>
            </div>

            <div className="follow-box">
              <div className="follow-num">
                100
              </div>

              <div className="follow-text">
                팔로잉
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 소개 */}
      <div className="profile-desc">
        에세이를 좋아하는 책린이 입니다!
        <br />
        instagram: xx_123
      </div>

      <div className="line"></div>

      {/* 책 스택 */}
      <div className="books-section">
        <div className="stack-message">
          현재 10.99cm만큼 쌓였어요!
          <br />
          조금 더 분발해요!
        </div>

        <div className="book-stack-wrap">
          <div className="shelf-top"></div>

          {books.map((book, index) => (
            <div
              className="book-item"
              key={index}
              onClick={() =>
                navigate("/review", {
                  state: book,
                })
              }
            >
              {book.title}
            </div>
          ))}

          <div className="shelf"></div>
        </div>
      </div>
    </div>
  );
}

export default Profile;
